<template><view class="login-page"><view class="brand"><text class="seal">念</text><text>一念 AI</text></view><view class="story"><text class="eyebrow">你的私人命名空间</text><text class="login-title">好名字，从一次认真登录开始</text><text class="story-copy">登录后与网页端共享项目、知识库、任务和开放平台数据。</text></view><view class="login-card"><text class="card-title">欢迎回来</text><input class="input" v-model.trim="email" type="text" placeholder="邮箱"/><input class="input" v-model="password" password placeholder="密码"/><button class="primary" :loading="loading" @click="submit">登录并进入</button><text class="hint">当前移动端第一版复用已有账号，请先在网页端完成注册或密码找回。</text></view></view></template>
<script setup>
import { ref } from 'vue'; import { api, saveSession } from '../../api'
const email=ref(''),password=ref(''),loading=ref(false)
async function submit(){if(!email.value||!password.value)return uni.showToast({title:'请填写邮箱和密码',icon:'none'});loading.value=true;try{const data=await api.login({email:email.value,password:password.value,device_name:'一念移动端'});saveSession(data);uni.reLaunch({url:'/pages/index/index'})}catch(e){uni.showToast({title:e.message,icon:'none',duration:2500})}finally{loading.value=false}}
</script>
<style scoped>.login-page{min-height:100vh;padding:calc(70rpx + env(safe-area-inset-top)) 42rpx 50rpx;background:linear-gradient(155deg,#3c2925 0,#7e3932 48%,#f5f1e9 48%)}.brand{display:flex;align-items:center;gap:18rpx;color:#fff;font-size:32rpx;font-weight:700}.seal{display:grid;place-items:center;width:66rpx;height:66rpx;background:#f3dfc3;color:#9c4137;border-radius:14rpx;font-size:38rpx}.story{padding:70rpx 6rpx 90rpx}.login-title{display:block;color:#fff;font-size:54rpx;line-height:1.35;font-weight:700}.story-copy{display:block;color:rgba(255,255,255,.7);font-size:25rpx;line-height:1.8;margin-top:22rpx}.login-card{background:#fffdf9;border-radius:30rpx;padding:42rpx 32rpx;box-shadow:0 24rpx 65rpx rgba(40,25,20,.2)}.card-title{display:block;font-size:40rpx;font-weight:700;margin-bottom:34rpx}.hint{display:block;text-align:center;color:#8a8177;font-size:21rpx;line-height:1.7;margin-top:26rpx}</style>
